    15	/**
    16	 * Given exact ideal numerators over a common positive denominator, distribute
    17	 * targetCents using largest remainders: floor EVERY signed ideal, then add one
    18	 * cent to entries with the greatest fractional remainders until the target is
    19	 * reached. Equal remainders favor the original line index, not line value,
    20	 * currency, sign, or tax-group traversal order. No caller arrays are mutated.
    21	 * The target is the rounded sum of the ideals (tax) or their exact sum (discount).
    22	 */
    23	function distribute(targetCents, numerators, denominator) {
    24	  const parts = numerators.map((numerator, index) => ({ ...floorParts(numerator, denominator), index }));
    25	  const floorSum = parts.reduce((sum, part) => sum + part.quotient, 0n);
    26	  const extras = Number(BigInt(targetCents) - floorSum);
    27	  const ranked = parts.slice().sort((a, b) => {
    28	    if (a.remainder !== b.remainder) return a.remainder > b.remainder ? -1 : 1;
    29	    return a.index - b.index;
    30	  });
    31	  for (let i = 0; i < extras; i += 1) ranked[i].quotient += 1n;
    32	  return parts.map(part => cents(part.quotient, 'allocated cents'));
    33	}
